/// Curated quotes for the home Sacred Sutra promo card.
///
/// Poetic bilingual EN/HI lines from Sacred Sutra daily quotes
/// (Mahabharata & Ramayana). Order is a fixed shuffle for variety.
/// Source: sacredsutra/lib/content/daily_quotes.dart
library;

class BeyondOwnedQuote {
  const BeyondOwnedQuote({
    required this.id,
    required this.epic,
    required this.en,
    required this.hi,
  });

  final String id;
  /// Catalog book id: `mahabharat`, `ramayan`, or `general`.
  final String epic;
  final String en;
  final String hi;

  String localized(String languageCode) =>
      languageCode == 'hi' ? hi : en;

  bool get isMahabharata => epic == kBeyondOwnedQuoteEpicMahabharat;
  bool get isRamayana => epic == kBeyondOwnedQuoteEpicRamayan;
  bool get isGeneral => epic == kBeyondOwnedQuoteEpicGeneral;
}

const String kBeyondOwnedQuoteEpicMahabharat = 'mahabharat';
const String kBeyondOwnedQuoteEpicRamayan = 'ramayan';
const String kBeyondOwnedQuoteEpicGeneral = 'general';

List<BeyondOwnedQuote> quotesForEpic(String bookId) {
  final id = bookId.trim();
  return beyondOwnedQuotes.where((q) => q.epic == id).toList();
}

BeyondOwnedQuote? quoteById(String id) {
  for (final q in beyondOwnedQuotes) {
    if (q.id == id) return q;
  }
  return null;
}

